UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nDiclofenac pottasium 50 mg<br />\r\nIndikasi :<br />\r\nObat ini termasuk golongan NSAID yang dapat mengurangi nyeri dan peradangan.<br />\r\nEfek Samping :<br />\r\nobat ini dapat mengiritasi lambung, untuk mencegahnya lebih baik meminum mylanta 30 menit sebelum makan, lalu minum kaditic setelah makan.<br />\r\nAturan Pakai :<br />\r\nDosis Umum: 100–150 mg per hari.<br />\r\nFrekuensi: Dibagi menjadi 2 sampai 3 kali minum dalam sehari (1 tablet setiap 8 atau 12 jam).<br />\r\nNyeri Ringan atau Jangka Panjang: Biasanya cukup 75–100 mg per hari (misal: 1 tablet, 2 kali sehari).<br />\r\nNyeri Haid atau Migrain: Dosis awal bisa 50 mg, jika masih nyeri bisa ditambah sesuai petunjuk dokter (maksimal 150 mg sehari).<br />\r\n&nbsp;</p>' WHERE `id_barang` = 34;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nAllopurinol 300 mg<br />\r\nIndikasi :<br />\r\nObat ini dapat digunakan untuk menurunkan kadar asam urat.<br />\r\nEfek Samping :<br />\r\nobat ini dapat mengiritasi lambung, wajib di minum setelah makan untuk meminimalisir iritasi lambung.<br />\r\ndisarankan banyak minum air putih, dan jangan menghentikan penggunaan tanpa saran dari dokter.<br />\r\nAturan Pakai :<br />\r\ndiminum 1 kali sehari, setelah makan.<br />\r\n&nbsp;</p>' WHERE `id_barang` = 35;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nMetampiron 500 mg, extract belladonna 10 mg, papaverine HCL 25 mg<br />\r\nIndikasi :<br />\r\nObat ini digunakan untuk meredakan nyeri sekaligus melemaskan otot yang tegang.<br />\r\nEfek Samping :<br />\r\nkandungan metampiron di dalamnya bisa memicu iritasi lambung. jika perlu, konsumsi sucralfate lebuh dahulu untuk melapisi lambung.<br />\r\nAturan Pakai :<br />\r\ndewasa : 1 tablet saat nyeri/kram muncul. jika nyeri berlanjut, bisa di ulang 6-8 jam (maksimal 3 kali sehari).<br />\r\n&nbsp;</p>' WHERE `id_barang` = 37;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nDiclofenac sodium 50mg, vitamin B1 50 mg, vitamin B6 50 mg, vitamin B12 100 mg<br />\r\nIndikasi :<br />\r\nObat ini di gunakan untuk mengatasi nyeri sedang hingga berat, terutama yang berhubungan dengan nyeri sendi.<br />\r\nEfek Samping :<br />\r\nobat ini dapat mengiritasi lambung, jika perlu mengonsumsi sucralfate terlebih dahulu untuk mecegah iritasi lambung.<br />\r\nAturan Pakai :<br />\r\ndewasa : 1 kaplet, 2 sampai 3 kali sehari. setelah makan.<br />\r\n&nbsp;</p>' WHERE `id_barang` = 38;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nTriamcinolone 4 mg<br />\r\nIndikasi :<br />\r\nObat ini termasuk dalam golongan kortikosteroid yang dapat mengurangi peradangan.<br />\r\nEfek Samping :<br />\r\npaling baik diminum pagi hari, setelah sarapan, untuk mengikuti ritme alami hormon tubuh dan mengurangi gangguan resiko lambung.<br />\r\nAturan Pakai :<br />\r\nDosis Awal: Biasanya berkisar antara 4 mg sampai 48 mg per hari.<br />\r\nKondisi Ringan: Dokter mungkin memulai dengan dosis rendah (4 mg - 8 mg).<br />\r\nKondisi Berat/Kronis: Dosis bisa dimulai dari angka yang lebih tinggi (di atas 16 mg) kemudian diturunkan secara bertahap ( tapering off ) setelah kondisi membaik.<br />\r\n&nbsp;</p>' WHERE `id_barang` = 40;
