UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nMadu, jahe, daun mint, buah adas, kayu ules, dan daun cengkeh<br />\r\nIndikasi :<br />\r\nUntuk meringankan gejala masuk angin serta meningkatkan daya tahan tubuh.<br />\r\nEfek Samping :<br />\r\naman dikonsumsi, namun tidak disarankan untuk wanita hamil dan menyusui. Untuk hasil terbaik, konsumsi sesuai dosis<br />\r\nAturan Pakai :<br />\r\ndiminum 3-4 sachet per hari saat gejala masuk angin.<br />\r\n&nbsp;</p>' WHERE `id_barang` = 51;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nTiap 5 ml: Aluminium hidroksida (200 mg), Magnesium hidroksida (200 mg), dan Simethicone/Dimetilpolisiloksan (80 mg)<br />\r\nIndikasi :<br />\r\nUntuk mengontrol asam lambung<br />\r\nEfek Samping :<br />\r\nhindari makan makanan asam seperti sambel, yang pedas pedas, perbanyak makanan berph basa seperti air kelapa muda, juz buah, sayur<br />\r\nAturan Pakai :<br />\r\nKocok dahulu sebelum diminum. Gunakan sendok takar (5 ml) yang tersedia dalam kemasan.<br />\r\nDewasa: 1-2 sendok takar (5-10 ml), 3-4 kali sehari.<br />\r\nAnak (6-12 tahun): 1/2-1 sendok takar (2,5-5 ml), 3-4 kali sehari Diminum sebelum makan atau 1-2 jam setelah makan dan menjelang tidur<br />\r\n&nbsp;</p>' WHERE `id_barang` = 52;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nParacetamol (Acetaminophen) 500 mg.<br />\r\nIndikasi :<br />\r\nObat ini untuk pereda nyeri dan penurun demam<br />\r\nEfek Samping :<br />\r\npenggunaan berlebihan dapat merusak fungsi hati. Hindari jika alergi paracetamol atau memiliki gangguan hati/ginjal berat.<br />\r\nAturan Pakai :<br />\r\nDewasa &amp; anak-anak &gt; 12 tahun: 1-2 kaplet, 3-4 kali sehari (maksimal 8 kaplet per 24 jam).<br />\r\n&nbsp;</p>' WHERE `id_barang` = 59;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\n500 mg Paracetamol dan 65 mg Kafein<br />\r\nIndikasi :<br />\r\nObat ini meredakan nyeri yang lebih intens dengan efek kerja yang lebih cepat dan kuat.<br />\r\nEfek Samping :<br />\r\nJangan diberikan kepada anak-anak di bawah umur 12 tahun,dan Jangan melebihi dosis yang dianjurkan.Hati-hati penggunaan obat ini pada penderita penyakit ginjal.<br />\r\nAturan Pakai :<br />\r\naturan pakai - Dewasa &amp; Anak-anak &gt; 12 tahun: 1 kaplet, ditelan dengan segelas air, 3-4 kali sehari. - Tidak melebihi 8 kaplet dalam 24 jam.<br />\r\n&nbsp;</p>' WHERE `id_barang` = 60;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nLevonorgestrel 0,15 mg (progestin) dan Ethinylestradiol 0,03 mg (estrogen).<br />\r\nIndikasi :<br />\r\nObat ini untuk mencegah kehamilan, mengatur siklus haid, serta mengurangi nyeri saat haid.<br />\r\nEfek Samping :<br />\r\nbukan untuk ibu menyusui Andalan Pil KB 56 tablet (kombinasi) dapat mengurangi produksi ASI. Untuk menyusui, disarankan menggunakan Andalan Laktasi.<br />\r\nAturan Pakai :<br />\r\ncara minum Mulailah pada hari pertama menstruasi, minum 1 tablet kuning setiap hari pada jam yang sama, dan langsung sambung strip baru setelah habis tanpa jeda<br />\r\n&nbsp;</p>' WHERE `id_barang` = 61;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\n10mg Hyoscine-N butylbromide (sebagai antispasmodik) dan 500 mg paracetamol<br />\r\nIndikasi :<br />\r\nObat ini untuk meredakan nyeri perut dan nyeri haid<br />\r\nEfek Samping :<br />\r\nUmumnya menyebabkan kantuk, mulut kering, konstipasi, atau pusing.Hindari penggunaan jangka panjang tanpa saran dokter dan kontraindikasi pada gangguan hati/ginjal<br />\r\nAturan Pakai :<br />\r\nDewasa 1-2 kaplet, 3 kali sehari (maksimal 6 kaplet/hari).<br />\r\n&nbsp;</p>' WHERE `id_barang` = 62;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nZat aktif Simvastatin 10 mg<br />\r\nIndikasi :<br />\r\nObat penurun kolesterol<br />\r\nEfek Samping :<br />\r\nrajin makan yang berserat contoh nya oatmeal, kacang-kacangan, sayuran, dan buah-buahan untuk membantu menjaga kadar obat dalam tubuh dan mendapatkan hasil yang optimal.<br />\r\nAturan Pakai :<br />\r\ndianjurkan untuk diminum malam hari pada waktu yang sama setiap hari<br />\r\n&nbsp;</p>' WHERE `id_barang` = 63;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nSetiap tablet mengandung 100 mg Vitamin B1 (Thiamine mononitra<br />\r\nIndikasi :<br />\r\nObat ini untuk mengatasi kebas, kesemutan, atau peradangan saraf<br />\r\nEfek Samping :<br />\r\nTidak ada pantangan makanan khusus saat mengonsumsi Neurobion Forte. Namun, mengonsumsi makanan bergizi seimbang secara umum mendukung kesehatan tubuh dan pemulihan saraf.<br />\r\nAturan Pakai :<br />\r\ndiminum satu kali sehari 1 tablet setelah makan<br />\r\n&nbsp;</p>' WHERE `id_barang` = 65;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nCetirizine hydrochloride (HCL) sebanyak 5mg setiap 5 ml (1 sendok takar)<br />\r\nIndikasi :<br />\r\nObat Ini digunakan untuk meredakan gejala alergi<br />\r\nEfek Samping :<br />\r\nobat ini dapat menyebabkan rasa kantuk disarankan untuk tidak berkendara setelah meminumnya dan segera konsultasi ke dokter jika terjadi reaksi alergi<br />\r\nAturan Pakai :<br />\r\nDewasa dan Anak &gt; 12 tahun: (2 sendok takar) sekali sehari. Anak 6 - 12 tahun: sendok takar sekali sehari<br />\r\nAnak 2 - 6 tahun: ( sendok takar) dua kali sehari atau 1 sendok takar sekali sehari<br />\r\n&nbsp;</p>' WHERE `id_barang` = 79;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nCefixime 100 mg per kapsul<br />\r\nIndikasi :<br />\r\nObat ini obat antibiotik<br />\r\nEfek Samping :<br />\r\nDapat dikonsumsi bersama makanan atau susu untuk mengurangi gangguan lambung.<br />\r\nAturan Pakai :<br />\r\nHarus digunakan berdasarkan petunjuk dokter.<br />\r\n&nbsp;</p>' WHERE `id_barang` = 80;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nMethyl salicylate 28%, Citronella oil/ minyak sereh 7.5%, Eucalyptus oil / minyak kayu putih 2.5%, Camphor 9%, Menthol 3%, Base ad 100%<br />\r\nIndikasi :<br />\r\nUntuk meredakan pegal linu, nyeri sendi<br />\r\nEfek Samping :<br />\r\nJangan menutup atau membungkus area yang baru diolesi dengan perban/kain ketat.<br />\r\nAturan Pakai :<br />\r\nOleskan secukupnya pada area tubuh yang sakit<br />\r\n&nbsp;</p>' WHERE `id_barang` = 84;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nDexamethasone sodium phosphate 1 mg, neomycin su<br />\r\nIndikasi :<br />\r\nObat ini untuk infeksi mata dengan peradangan<br />\r\nEfek Samping :<br />\r\nJika timbul reaksi alergi atau iritasi yang memburuk, segera hentikan penggunaan dan konsultasikan dengan dokter.<br />\r\nAturan Pakai :<br />\r\nCuci tangan sebelum digunakan, tarik kelopak bawah, teteskan obat, dan tutup mata 1-2 menit<br />\r\n&nbsp;</p>' WHERE `id_barang` = 88;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nFradiomycin Sulfate 2,5 mg (Neomycin) dan Gramicidin-S HCl 1 mg<br />\r\nIndikasi :<br />\r\nObat ini digunakan untuk mengatasi infeksi bakteri radang tenggorokan<br />\r\nEfek Samping :<br />\r\nhindari makanan pedas dan berminyak perbanyak minum air putih<br />\r\nAturan Pakai :<br />\r\nLarutkan perlahan di dalam mulut atau di bawah lidah sampai habis. Meskipun radang sudah membaik, habiskan seluruh dosis sesuai anjuran dokter untuk mencegah bakteri kebal<br />\r\n&nbsp;</p>' WHERE `id_barang` = 90;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nGraptophyllum pictum folium (Daun Ungu) 90 mg, Sophorae japonicae flos (Bunga Sophora) 85 mg, Rubia cordifoliae radix (Akar Rubia) 10 mg<br />\r\nIndikasi :<br />\r\nObat herbal untuk meringankan wasir atau ambeien<br />\r\nEfek Samping :<br />\r\nTidak disarankan untuk anak-anak, ibu hamil, dan menyusui tanpa konsultasi dokter obat ini .Hindari mengemudi atau mengoperasikan mesin setelah mengonsumsi obat ini jika terasa mengantuk<br />\r\nAturan Pakai :<br />\r\ndiminum 2 kapsul, 3 kali sehari setelah makan.<br />\r\n&nbsp;</p>' WHERE `id_barang` = 94;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nIbuprofen 200 mg, Paracetamol 500 mg<br />\r\nIndikasi :<br />\r\nNyeri otot dan sendi, pegal linu<br />\r\nEfek Samping :<br />\r\nEfek samping Mual, muntah, sembelit, reaksi kulit, sakit kepala. Penggunaan jangka lama dan dosis besar dapat menimbulkan kerusakan hati dan pendarahan di gastrointestinal.<br />\r\nSaran : - obat ini mengiritasi lambung, jika perlu gunakan sucralfate untuk melapisi lambung<br />\r\n- obat ini meningkatkan tekanan darah, jika perlu gunakan obat penurun tekanan darah<br />\r\nAturan Pakai :<br />\r\ndiminum tiap 8 jam sekali sesudah makan<br />\r\n&nbsp;</p>' WHERE `id_barang` = 99;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nMg(OH)2 325 mg, Al(OH)3 325 mg, Dimethylpolysiloxane 50 mg<br />\r\nIndikasi :<br />\r\nSakit maag, Gastritis, Tukak lambung dan/atau usus halus, Esofagitis, Pirosis, Perut kembung<br />\r\nEfek Samping :<br />\r\nmenganggu penyerapan asam folat dan zat besi<br />\r\nSaran : hindari makanan pedas, bertepung, kelola stress<br />\r\nAturan Pakai :<br />\r\ndiminum 1 jam sesudah makan dan sebelum tidur malam, tablet dikunyah sampai halus sebelum ditelan<br />\r\n&nbsp;</p>' WHERE `id_barang` = 101;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nSerbuk krim nabati, Dekstrosa, Campuran bakteri laktat (Lactobacillus Acidophilus, Bifidobacterium Longum, Streptococcus Thermophillus), Vitamin C 10 mg, Vitamin B1 0,5 mg, Vitamin B2 0,5 mg, Vitamin B6 0,5 mg, Niacin 0,5 mg, Zinc Oxide<br />\r\nIndikasi :<br />\r\nTerapi pengobatan diare dan intoleransi laktosa.<br />\r\nEfek Samping :<br />\r\nReaksi efek samping yang mungkin terjadi diantaranya: perut kembung, rasa tidak nyaman pada perut, adanya reaksi alergi pada bakteri laktat (Lactobacillus Acidophilus, Bifidobacterium Longum, Streptococcus Thermophillus) yang biasanya ditandai dengan adanya pembengkakan pada wajah, bibir, lidah, atau tenggorokan atau gatal-gatal dan kemerahan pada kulit.<br />\r\nsaran : perbanyak minum air putih<br />\r\nAturan Pakai :<br />\r\ndiminum tiap 8 jam sekali. Dapat dikonsumsi langsung dengan melarutkannya bersama air putih atau dikonsumsi bersama makanan untuk mengurangi ketidak-nyamanan pencernaan.<br />\r\n&nbsp;</p>' WHERE `id_barang` = 103;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nTiap tablet mengandung Vitamin A 1000 IU, Vitamin B1 1.4mg, Vitamin B2 1.6mg, Vitamin B3 9mg, Vitamin B6 2mg, Vitamin B12 3mcg, Vitamin C 60mg, Vitamin D3 100IU, Vitamin E 5mg, Kalsium Pan<br />\r\nIndikasi :<br />\r\nMembantu menjaga kesehatan anak-anak dan membantu memenuhi kebutuhan multivitamin untuk anak-anak di usia pertumbuhan dan masa penyembuhan setelah sakit.<br />\r\nEfek Samping :<br />\r\n-Mengandung pemanis buatan Aspartame &amp; Sukralosa<br />\r\n-Tidak dianjurkan pada penderita Feniketonuria dan wanita hamil dengan katar fenilalanin tinggi.<br />\r\n- Tidak boleh digunakan pada anak dibawah usia 1 tahun<br />\r\nAturan Pakai :<br />\r\ndiminum tiap 8 jam sekali 1 tab dihisap atau dikunyah<br />\r\n&nbsp;</p>' WHERE `id_barang` = 104;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nTiap tablet mengandung Vitamin A 1000 IU, Vitamin B1 1.4mg, Vitamin B2 1.6mg, Vitamin B3 9mg, Vitamin B6 2mg, Vitamin B12 3mcg, Vitamin C 60mg, Vitamin D3 100IU, Vitamin E 5mg, Kalsium Pan<br />\r\nIndikasi :<br />\r\nMembantu menjaga kesehatan anak-anak. Membantu memenuhi kebutuhan multivitamin untuk anak-anak di usia pertumbuhan dan masa penyembuhan setelah sakit<br />\r\nEfek Samping :<br />\r\n- Mengandung pemanis buatan Aspartame &amp; Sukralosa<br />\r\n- Tidak dianjurkan pada penderita Feniketonuria dan wanita hamil dengan katar fenilalanin tinggi.<br />\r\n- Tidak boleh digunakan pada anak dibawah usia 1 tahun<br />\r\nAturan Pakai :<br />\r\ndiminum tiap 8 jam sekali 1 tab dihisap<br />\r\n&nbsp;</p>' WHERE `id_barang` = 105;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nTiap mL larutan isotonik steril mengandung: Tetrahydrozoline HCl 0.05% b/v, Benzalkonium Chloride 0.01% b/v<br />\r\nIndikasi :<br />\r\nMata merah oleh iritasi ringan karena debu, asap, angin, dan setelah berenang.<br />\r\nEfek Samping :<br />\r\nMata terasa pedih, rasa terbakar dan reaksi hiperemia pada pemakaian yang berlebihan<br />\r\nAturan Pakai :<br />\r\nDiteteskan pada mata yang merah/teriritasi 2-3 tetes pada setiap mata, 3-4 kali sehari atau sesuai anjuran dokter.<br />\r\n&nbsp;</p>' WHERE `id_barang` = 106;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\n5.67 g ekstrak bahan : Oryza sativa 20%, foeniculum vulgare fructus 10%, helicteres isora fructus 10%, zingiber officinale rhizoma, myristica fragrans semen, cinnamomum burmanni cotex, cen<br />\r\nIndikasi :<br />\r\nMeringankan gejala masuk angin, menjaga daya tahan tubuh.<br />\r\nEfek Samping :<br />\r\nPemakaian obat umumnya memiliki efek samping tertentu dan sesuai dengan masing-masing individu. Obat ini tidak direkomendasikan untuk wanita hamil<br />\r\nAturan Pakai :<br />\r\nUntuk membantu menjaga daya tahan tubuh: minum 1 sachet, 2 kali per hari. Selama 7 hari atau lebih.<br />\r\nJika masuk angin/sakit perut dan diare: minum 3-4 sachet per hari.<br />\r\n&nbsp;</p>' WHERE `id_barang` = 107;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nMetronidazole 125 mg/ 5 ml<br />\r\nIndikasi :<br />\r\nUntuk infeksi karena mikrooganisme yang peka terhadap metronidazole seperti amebiasis, urogenital trichomoniasis, dan vaginitis non-spesifik.<br />\r\nEfek Samping :<br />\r\nEfek samping yang mungkin terjadi dalam penggunaan obat adalah : Sakit kepala, pusing, vertigo, mual, muntah, diare, konstipasi, eritema, ruam, trombositopenia.<br />\r\nAturan Pakai :<br />\r\nPENGGUNAAN OBAT INI HARUS SESUAI DENGAN PETUNJUK DOKTER. Dewasa: susp. Diminum 1 jam sebelum makan. Amubiasis: dewasa; intestinal amubiasis: sehari 3 x 750 mg selama 5-10 hari. Anak : 35-50 mg/kgBB/hari dibagi dalam 3 dosis selama 5-10 hari. Hepatic amobiasis: sehari 3 x 750 mg selama 5-10 hari. Anak: 35-50 mg/<br />\r\nDiberikan saat perut kosong atau 1 jam sebelum makan.<br />\r\n&nbsp;</p>' WHERE `id_barang` = 108;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nBetamethasone-17-valerate 0.1%, Neomycin sulphate 0.5%<br />\r\nIndikasi :<br />\r\nMeringankan inflamasi dari dermatosis yang responsif terhadap kortikosteroid bila terkomplikasi dengan infeksi sekunder yang disebabkan oleh organisme yang rentan terhadap neomisin<br />\r\nEfek Samping :<br />\r\nRasa terbakar, gatal, iritasi, kulit kering, folikulitis, hipertrikosis, erupsi yang menyerupai alergi, maserasi kulit, infeksi sekunder, atropi kulit, striae, miliaria. Ototoksisitas dan nefrotoksisitas (terapi jangka panjang atau dosis besar)<br />\r\nAturan Pakai :<br />\r\noles tipis pagi dan malam<br />\r\n&nbsp;</p>' WHERE `id_barang` = 109;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nAmlodipine (sebagai Amlodipine Besylate) 10 mg.<br />\r\nIndikasi :<br />\r\nUntuk pengobatan hipertensi<br />\r\nEfek Samping :<br />\r\nEfek samping amlodipine yang paling umum terjadi adalah edema perifer (bengkak pada pergelangan kaki) dan sakit kepala. Efek samping lain yang mungkin terjadi meliputi pusing, kelelahan, jantung berdebar (palpitasi), dan kemerahan pada wajah (flushing).<br />\r\nAturan Pakai :<br />\r\ndiminum 1 dd 1 malam (istirahat) atau petunjuk dokter<br />\r\n&nbsp;</p>' WHERE `id_barang` = 110;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nAmlodipine 5 mg<br />\r\nIndikasi :<br />\r\nUntuk pengobatan lini pertama hipertensi<br />\r\nEfek Samping :<br />\r\nefek samping Sakit kepala, pusing, mengantuk, debaran jantung, sakit perut, mual, edema, kelelahan.<br />\r\nAturan Pakai :<br />\r\ndiminum 1 dd 1 tab mala (istirahat) atau petunjuk dokter<br />\r\n&nbsp;</p>' WHERE `id_barang` = 111;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nEkstrak Lumbricus rubellus (cacing tanah)<br />\r\nIndikasi :<br />\r\nMembantu meredakan demam, tipes<br />\r\nEfek Samping :<br />\r\nPemakaian obat umumnya memiliki efek samping tertentu dan sesuai dengan masing-masing individu.<br />\r\nAturan Pakai :<br />\r\nDewasa: 2 kapsul, 3 kali per hari Anak-anak: 1 kapsul, 3 kali per hari. Sesudah makan<br />\r\n&nbsp;</p>' WHERE `id_barang` = 114;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nTiap kapsul lunak mengandung: Folic Acid 1 mg, Beta-carotene 10.000 IU, Vitamin B1 3 mg, Vitamin B2 3.4 mg, Nicotinamide 20 mg, Vitamin B6 2 mg, Calcium D-pantothenate 7.5 mg, Calcium Carb<br />\r\nIndikasi :<br />\r\nSebagai suplemen multivitamin dan mineral untuk membantu memenuhi kebutuhan nutrisi selama masa kehamilan.<br />\r\nEfek Samping :<br />\r\nEfek samping yang mungkin terjadi meliputi gangguan pencernaan ringan seperti mual atau sembelit, serta feses yang berwarna kehitaman karena kandungan zat besi.<br />\r\nAturan Pakai :<br />\r\ndiminum 1 dd 1 cap sesudah makan<br />\r\n&nbsp;</p>' WHERE `id_barang` = 117;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nCyproheptadine HCl 4 mg<br />\r\nIndikasi :<br />\r\nAlergi: urtikaria dan angioedema, cold urticaria, allergic rhinitis, vasomotor rhinitis<br />\r\nEfek Samping :<br />\r\nEfek samping yang paling umum adalah rasa kantuk. Efek samping lain meliputi mulut kering, pusing, mual, dan penambahan berat badan.<br />\r\nAturan Pakai :<br />\r\nDewasa: 1 kaplet, diminum 3 kali sehari.<br />\r\nAnak 7-14 tahun: 1 kaplet, diminum 2-3 kali sehari.<br />\r\nAnak 2-6 tahun: ½ kaplet, diminum 2-3 kali sehari.<br />\r\n&nbsp;</p>' WHERE `id_barang` = 129;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nMetformin Hydrochloride 500 mg<br />\r\nIndikasi :<br />\r\nSebagai monoterapi atau terapi kombinasi dengan agen antidiabetik lain atau insulin, untuk kontrol glikemik pada pasien dewasa dengan diabetes melitus tipe<br />\r\nEfek Samping :<br />\r\nEfek samping yang mungkin terjadi dalam penggunaan obat adalah: - Sangat Umum (&gt;10%): Diare, mual, muntah, nyeri abdomen, kehilangan nafsu makan. - Jarang (&lt;0.01%): Asidosis Laktat (efek samping serius, memerlukan intervensi medis segera), penurunan absorpsi vitamin B12 pada penggunaan jangka panjang, hepatitis.<br />\r\nAturan Pakai :<br />\r\nDosis bersifat individual. Dosis awal lazim: 500 mg 1-2 kali sehari. Dosis dapat dititrasi naik setiap 1-2 minggu hingga dosis efektif tercapai (maksimum 2550 mg/hari). atau menurut petunjuk dokter<br />\r\nMinum obat bersamaan atau segera sesudah makan untuk meminimalkan efek samping gastrointestinal.<br />\r\n&nbsp;</p>' WHERE `id_barang` = 130;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nTiap 0.6ml mengandung Paracetamol 60mg<br />\r\nIndikasi :<br />\r\nNyeri &amp; demam.<br />\r\nEfek Samping :<br />\r\nReaksi hematologi, kulit &amp; reaksi alergi lain<br />\r\nAturan Pakai :<br />\r\nTetes Anak &lt; 1 thn 0.6 mL, 1-2 thn 0.6-1.2 mL diberikan 3 - 4 kali sehari<br />\r\nnote : 10mg paracetamol untuk 1kg BB.<br />\r\n&nbsp;</p>' WHERE `id_barang` = 143;
