UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nParacetamol 160 mg/5ml<br />\r\nIndikasi :<br />\r\nPenurun demam dan pereda rasa nyeri<br />\r\nEfek Samping :<br />\r\nDosis besar menyebapkan kerusakan hati<br />\r\nAturan Pakai :<br />\r\nDewasa : 3-4 x sehari 15-30ml, maksimal 120 mL sehari. 7-12 th : 3-4 kali sehari 10ml. 4-6 th : 3-4 kali sehari 5ml. 1-3 th : 3-4 kali 2.5-5ml. 6-12 bln :3-4 x sehari 2.5ml setelah makan<br />\r\n&nbsp;</p>' WHERE `id_barang` = 171;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nIbuprofen 100 mg/5 ml<br />\r\nIndikasi :<br />\r\nPereda nyeri dan penurun demam<br />\r\nEfek Samping :<br />\r\nobat ini mempunyai efek samping Sakit perut, mual, muntah, sakit kepala, diare, sembelit, pusing, atau mengantuk<br />\r\nAturan Pakai :<br />\r\ndewasa 400 mg 3 sampai 4 kali perhari. Analgesik: 200 sampai 400 mg 3 hingga 4 kali perhari, maksimum: 2400 mg perhari. Anak usia 8 hingga 12 tahun 200 mg 3 sampai 4 kali perhari, 3 hingga 7 tahun 100 mg 3 sampai 4 kali perhari, 1 hingga 2 tahun 50 mg 3 sampai 4 kali perhari,setelah makan,kocok terlebih dahulu sebelum di minum<br />\r\n&nbsp;</p>' WHERE `id_barang` = 172;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nIbuprofen 200mg/5ml<br />\r\nIndikasi :<br />\r\nPereda nyeri dan penurun demam<br />\r\nEfek Samping :<br />\r\nobat ini mempunyai efek samping Sakit perut, mual, muntah, sakit kepala, diare, sembelit, pusing, atau mengantuk<br />\r\nAturan Pakai :<br />\r\nkocok terlebih dahlu,dewasa 400 mg 3 sampai 4 kali perhari. Analgesik: 200 sampai 400 mg 3 hingga 4 kali perhari, maksimum: 2400 mg perhari. Anak usia 8 hingga 12 tahun 200 mg 3 sampai 4 kali perhari, 3 hingga 7 tahun 100 mg 3 sampai 4 kali perhari, 1 hingga 2 tahun 50 mg 3 sampai 4 kali perhari<br />\r\n&nbsp;</p>' WHERE `id_barang` = 173;
