UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nParacetamol 120 mg/ 5 ml<br />\r\nIndikasi :<br />\r\nPenurun demam dan pereda nyeri<br />\r\nEfek Samping :<br />\r\ndapat menyebabkan alergi kulit dan merusak fungsi hati apabila overdosis<br />\r\nAturan Pakai :<br />\r\nAnak (9-12 tahun) : 15-20 ml, diberikan 3-4 kali sehari. Anak (6 - 9 tahun) : 10 ml - 15 ml, diberikan 3-4 kali per hari. Anak (2 - 6 tahun) : 5 ml - 10 ml, diberikan 3-4 kali per hari. Bayi (1 - 2 tahun) : 5 ml , diberikan 3-4 kali per hari.setelah makan<br />\r\n&nbsp;</p>' WHERE `id_barang` = 175;
