UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nAmlodipine 10mg<br />\r\nIndikasi :<br />\r\nObat ini untuk menurunkan tensi<br />\r\nEfek Samping :<br />\r\nobat ini memiliki efek samping edema (pembengkakan kaki atau pergelangan kaki), sakit kepala.<br />\r\nAturan Pakai :<br />\r\numumnya obat ini dimulai dari dosis 5mg dan dapat di tingkatkan menjadi maksimal 10mg perhari. obat ini diminum pada malam hari untuk memaksimalkan efektivitasnya dalam mengontrol tekanan darah (hipertensi) sepanjang malam hingga ke esokan harinya. dan sebaiknya di jam yang sama setiap harinya<br />\r\n&nbsp;</p>' WHERE `id_barang` = 195;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nCandesartan cilexetil 8 mg.<br />\r\nIndikasi :<br />\r\nObat ini untuk menurunkan tensi<br />\r\nEfek Samping :<br />\r\numunya pusing dan sakit kepala<br />\r\nAturan Pakai :<br />\r\ndiminum sekali sehari pada malam hari (atau sesuai aturan dokter)<br />\r\n&nbsp;</p>' WHERE `id_barang` = 209;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nKetoconazole 2%<br />\r\nIndikasi :<br />\r\nMengobati infeksi jamur kulit seperti panu, kurap, kutu air.<br />\r\nEfek Samping :<br />\r\numumnya ringan seperti iritasi, rasa panas/terbakar, atau pruritis (gatal) pada area yang di olesi.<br />\r\nAturan Pakai :<br />\r\noleskan cream tipis tipis pada area yang terinfeksi, umumnya digunakan 1 kali sehari. untuk infeksi yang resisten dapat digunakan tiap 12 jam sehari<br />\r\n&nbsp;</p>' WHERE `id_barang` = 211;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nKetoconazole 200 mg.<br />\r\nIndikasi :<br />\r\nObat ini untuk infeksi jamur<br />\r\nEfek Samping :<br />\r\nefek samping obat ini adalah gangguan lambung, usus, gatal gatal.<br />\r\nAturan Pakai :<br />\r\nuntuk aturan minum 1 kali sehari pada malam hari<br />\r\n&nbsp;</p>' WHERE `id_barang` = 212;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nSimvastatin 10 mg.<br />\r\nIndikasi :<br />\r\nObat ini digunakan untuk menurunkan kadar kolestro.<br />\r\nEfek Samping :<br />\r\nobat ini memiliki efek samping seperti mual, sakit kepala,perut kembung dan sakit perut<br />\r\nAturan Pakai :<br />\r\ndewasa: 10-20mg per hari. dosis dapat ditingkatkan hingga maksimal 40mg perhari.<br />\r\n&nbsp;</p>' WHERE `id_barang` = 216;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nPer 5 ml mengandung Paraffin Liquidum 1.5 gram, Phenolphthalein 75 mg, Glycerin 1 gram.<br />\r\nIndikasi :<br />\r\nObat ini untuk melancarkan BAB<br />\r\nEfek Samping :<br />\r\nobat ini memiliki efek samping seperti kram usus.<br />\r\nAturan Pakai :<br />\r\ndewasa; 2 sendok takar (10ml). anak &gt;6-12 tahun; 1 sendok takar (5ml) pada malam hari<br />\r\n&nbsp;</p>' WHERE `id_barang` = 218;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nThiampenicol 500mg<br />\r\nIndikasi :<br />\r\nAntibiotik ini mengatasi infeksi bakteri serius dan infeksi tertentu yang peka terhadap thiamphenicol<br />\r\nEfek Samping :<br />\r\nbeberapa efek samping yang mungkin timbul antara lain seperti sakit kepala, mual, muntah, diare, sariawan, radang lidah, dan adanya resiko gangguan darah terutama jika dipakai jangka panjang<br />\r\nAturan Pakai :<br />\r\nobat ini sebaiknya diminum saat perut kosong, 1 jam sebelum atau 2 jam sesudah makan untuk penyerapan optimal. harus menggunakan resep dokter<br />\r\n&nbsp;</p>' WHERE `id_barang` = 226;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nTretinoin (Retinoic Acid) 0,05 %<br />\r\nIndikasi :<br />\r\nDigunakan untuk mengatasi jerawat dan membantu memperbaiki kulit<br />\r\nEfek Samping :<br />\r\nDi pagi dan siang hari, setelah membersihkan wajah, gunakan sunscreen (SPF 30 ke atas) untuk melindungi kulit dari sinar matahari karena kulit menjadi lebih sensitif akibat tretinoin.<br />\r\nAturan Pakai :<br />\r\nDigunakan dengan cara dioleskan tipis pada kulit yang berjerawat 1 kali sehari pada malam hari<br />\r\n&nbsp;</p>' WHERE `id_barang` = 233;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nCefadroxil monohydrate 500 mg<br />\r\nIndikasi :<br />\r\nObat antibiotik ini digunakan untuk mengobati infeksi bakteri, seperti infeksi saluran pernapasan.<br />\r\nEfek Samping :<br />\r\nefek samping ringan seperti mual atau nyeri lambung, dapat diberikan obat lambung seperti antasida (diminum dengan jarak waktu minimal 2 jam dari antibiotik). Bila terjadi diare ringan, dapat diberikan oralit untuk mencegah dehidrasi dan probiotik untuk membantu menjaga keseimbangan bakteri usus<br />\r\nAturan Pakai :<br />\r\nDosis dewasa 2 kali sehari (setiap 12 jam) sesuai anjuran dokter. habiskan<br />\r\n&nbsp;</p>' WHERE `id_barang` = 235;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nGlimepiride 1 mg<br />\r\nIndikasi :<br />\r\nDigunakan untuk menurunkan kadar gula darah.<br />\r\nEfek Samping :<br />\r\nEfek samping pusing, mual, gula darah rendah. Konsumsi makanan ringan jika merasa lemas atau pusing.<br />\r\nAturan Pakai :<br />\r\nDiminum 1 kali sehari sebelum makan.<br />\r\n&nbsp;</p>' WHERE `id_barang` = 237;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nGlimepiride 2 mg<br />\r\nIndikasi :<br />\r\nDigunakan untuk menurunkan kadar gula darah.<br />\r\nEfek Samping :<br />\r\nEfek samping pusing, mual, gula darah rendah. Konsumsi makanan ringan jika merasa lemas atau pusing.<br />\r\nAturan Pakai :<br />\r\nDiminum 1 kali sehari sebelum makan.<br />\r\n&nbsp;</p>' WHERE `id_barang` = 238;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nFerrous Gluconate 250 mg, Vitamin C 50 mg, Asam folat (Folic Acid) 400–1000 mcg, Vitamin B12 7.5 mcg, Mineral lain (Manganese, Copper)<br />\r\nIndikasi :<br />\r\nDigunakan untuk mengatasi anemia atau kekurangan zat besi.<br />\r\nEfek Samping :<br />\r\nEfek samping mual, perut kembung. Hindari makanan pedas/berlemak jika perut terasa tidak nyaman.<br />\r\nAturan Pakai :<br />\r\nDosis umum 1 kapsul sehari.<br />\r\n&nbsp;</p>' WHERE `id_barang` = 239;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nDesoximetasone 0,25%<br />\r\nIndikasi :<br />\r\nDigunakan untuk mengurangi peradangan dan nyeri pada kulit akibat ruam, alergi, atau luka ringan.<br />\r\nEfek Samping :<br />\r\nEfek samping kulit kemerahan atau iritasi ringan. Hentikan penggunaan jika muncul iritasi parah dan jangan oles terlalu tebal.<br />\r\nAturan Pakai :<br />\r\nDioleskan tipis pada area yang sakit 2 kali sehari.<br />\r\n&nbsp;</p>' WHERE `id_barang` = 244;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nClobetasol propionate 0.05%<br />\r\nIndikasi :<br />\r\nDigunakan untuk mengurangi peradangan dan gatal pada kulit, misalnya eksim atau dermatitis.<br />\r\nEfek Samping :<br />\r\nEfek samping: kulit iritasi, kemerahan, atau kering. Gunakan tipis, jangan terlalu sering, dan hentikan jika muncul reaksi parah.<br />\r\nAturan Pakai :<br />\r\nDioleskan tipis pada area kulit yang bermasalah 2 kali sehari.<br />\r\n&nbsp;</p>' WHERE `id_barang` = 245;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nNatrium lauril sulfoasetat, Natrium sitrat, Sorbitol, Polyethylene glycol (PEG) 400<br />\r\nIndikasi :<br />\r\nDigunakan untuk mengatasi sembelit (konstipasi), melunakkan feses yang keras, serta membantu pengosongan usus sebelum tindakan medis tertentu seperti pemeriksaan rektal. Cocok saat sulit BAB dan membutuhkan efek yang bekerja cepat.<br />\r\nEfek Samping :<br />\r\nGunakan sesuai aturan pakai dan jangan terlalu sering tanpa anjuran dokter karena bisa menyebabkan iritasi atau ketergantungan pencahar. Perbanyak minum air putih, konsumsi serat, dan olahraga ringan untuk membantu mencegah sembelit berulang.<br />\r\nAturan Pakai :<br />\r\nBuka tutup tube, oleskan sedikit gel pada ujung aplikator sebagai pelicin. Masukkan ujung tube ke anus (pada anak cukup sebagian), lalu tekan hingga isi gel habis. Tetap tekan tube saat menarik keluar. digunakan 1 tube sekali pakai, efek bekerja dalam 5–15 menit.<br />\r\n&nbsp;</p>' WHERE `id_barang` = 251;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nIbuprofen 400 mg<br />\r\nIndikasi :<br />\r\nDigunakan untuk meredakan nyeri ringan sampai sedang seperti sakit kepala, sakit gigi, nyeri otot dan sendi, nyeri haid, serta menurunkan demam<br />\r\nEfek Samping :<br />\r\nefek samping ringan seperti mual, nyeri lambung, atau perih ulu hati, dapat diberikan obat pelindung lambung seperti antasida atau obat penghambat pompa proton (misal omeprazole) sesuai anjuran dokter<br />\r\nAturan Pakai :<br />\r\nDosis 1 tablet per 8 jam<br />\r\n&nbsp;</p>' WHERE `id_barang` = 252;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nLevonorgestrel 0,15 mg, Ethinylestradiol 0,03 mg<br />\r\nIndikasi :<br />\r\nDigunakan untuk mencegah kehamilan dengan cara mencegah ovulasi (pelepasan sel telur), mengentalkan lendir serviks, dan menipiskan lapisan rahim sehingga sperma sulit mencapai sel telur.<br />\r\nEfek Samping :<br />\r\nPerhatikan reaksi tubuh seperti mual ringan, sakit kepala, nyeri payudara, atau flek perdarahan awal; bila gejala persisten atau berat, konsultasikan ke dokter.<br />\r\nAturan Pakai :<br />\r\nDiminum 1 tablet per hari secara teratur, pada waktu yang sama setiap hari selama 28 hari berturut-turut sesuai urutan pada blister tanpa jeda antar strip.<br />\r\n&nbsp;</p>' WHERE `id_barang` = 254;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nMethylprednisolone 4 mg<br />\r\nIndikasi :<br />\r\nObat untuk radang dan nyeri<br />\r\nEfek Samping :<br />\r\nobat ini menurunkan sistem imun, mengiritasi lambung, dan meningkatkan osteoporosis. Disarankan konsumsi vitamin daya tahan tubuh, penetral asam lambung dan suplemen calsium<br />\r\nAturan Pakai :<br />\r\nDiminum 1 tablet tiap 8 jam<br />\r\n&nbsp;</p>' WHERE `id_barang` = 260;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nTetrahydrozoline HCl 0.05%<br />\r\nIndikasi :<br />\r\nDigunakan untuk meredakan mata kering, perih, atau iritasi ringan.<br />\r\nEfek Samping :<br />\r\nEfek samping: mata terasa pedih sementara atau kemerahan ringan. Jangan sentuh ujung botol ke mata dan simpan di tempat bersih; hentikan jika iritasi bertambah.<br />\r\nAturan Pakai :<br />\r\nTeteskan 1–2 tetes ke setiap mata 2–3 kali sehari atau sesuai anjuran dokter.<br />\r\n&nbsp;</p>' WHERE `id_barang` = 262;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nSalbutamol sulfate 1.2 mg, Theophylline (teofilin) 130 mg<br />\r\nIndikasi :<br />\r\nDigunakan untuk gangguan sirkulasi darah perifer seperti penyakit pembuluh darah tepi<br />\r\nEfek Samping :<br />\r\nEfek samping yang mungkin muncul meliputi pusing, mual, jantung berdebar, atau kemerahan pada kulit. Jika muncul keluhan berat seperti nyeri dada atau reaksi alergi, segera hentikan dan konsultasikan ke dokter.<br />\r\nAturan Pakai :<br />\r\n3 kali sehari setelah makan untuk mengurangi iritasi lambung.<br />\r\n&nbsp;</p>' WHERE `id_barang` = 263;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nAcyclovir 400mg<br />\r\nIndikasi :<br />\r\nObat anti virus<br />\r\nEfek Samping :<br />\r\nJika terjadi efek samping yang berlebih dan berbahaya, harap konsultasikan kepada tenaga medis.<br />\r\nAturan Pakai :<br />\r\nDewasa : 5 kali sehari 800 mg tiap 4 jam selama 7 hari.<br />\r\n&nbsp;</p>' WHERE `id_barang` = 264;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nDequalinium Chloride 0,25 mg, (ryan rahma zaky)<br />\r\nIndikasi :<br />\r\nObat ini digunakan untuk meredakan sakit tenggorokan<br />\r\nEfek Samping :<br />\r\nHentikan penggunaan jika muncul reaksi alergi atau bila keluhan tidak membaik dalam beberapa hari.<br />\r\nAturan Pakai :<br />\r\ndapat digunakan setiap 3–4 jam sesuai kebutuhan dengan maksimal 8 tablet per hari<br />\r\n&nbsp;</p>' WHERE `id_barang` = 265;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nVitamin C 500mg<br />\r\nIndikasi :<br />\r\nVitamin untuk sariawan dan menjaga daya tahan tubuh<br />\r\nEfek Samping :<br />\r\nminum air putih yang cukup untuk membantu proses penyerapan vitamin dan makan buah-buahan yg bernutrisi.<br />\r\nAturan Pakai :<br />\r\ndosis : 1-2 tablet dalam sehari setelah makan, di hisap seperti permen.<br />\r\n&nbsp;</p>' WHERE `id_barang` = 269;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nPovidone Iodine 10%<br />\r\nIndikasi :<br />\r\nAntiseptic ini untuk pertolongan pertama pada Luka lecet, Luka tersayat, dan infeksi kulit.<br />\r\nEfek Samping :<br />\r\nsebaiknya di tambah dengan obat anti nyeri untuk membantu proses penyembuhan.<br />\r\nAturan Pakai :<br />\r\nbersihkan dan keringkan area luka, lalu oleskan atau kompres Betadine menggunakan kapas/kasa 1-3 kali sehari, biarkan kering sejenak, lalu tutup luka dengan perban atau plester steril jika diperlukan.<br />\r\n&nbsp;</p>' WHERE `id_barang` = 270;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nPirantel pamoat 250mg/tab<br />\r\nIndikasi :<br />\r\nObat ini untuk mengobati cacingan.<br />\r\nEfek Samping :<br />\r\ndisarankan seluruh anggota keluarga meminum obat cacing secara bersamaan agar tidak terjadi infeksi ulang. Potong kuku, cuci tangan dengan sabun sebelum makan dan setelah dari toilet.<br />\r\nAturan Pakai :<br />\r\nDewasa: 1–2 tablet sekali minum. sesudah makan. ulangi peminuman dosis pada hari ke 14 setelah minum dosis pertama.<br />\r\n&nbsp;</p>' WHERE `id_barang` = 272;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nNystatin 100.000 IU.<br />\r\nIndikasi :<br />\r\nUntuk mengatasi jamur di mulut<br />\r\nEfek Samping :<br />\r\nuntuk membantu proses penyembuhan, makan buah-buahan yang mengandung vitamin C<br />\r\nAturan Pakai :<br />\r\nkocok dahulu sebelum di gunakan, teteskan pada area yang terkena sariawan.<br />\r\n&nbsp;</p>' WHERE `id_barang` = 278;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nThiamphenicol 125mg/5ml.<br />\r\nIndikasi :<br />\r\nAntibiotik untuk tipes.<br />\r\nEfek Samping :<br />\r\nhabiskan antibiotik meskipun gejala sudah membaik.<br />\r\nAturan Pakai :<br />\r\nlarutkan dengan air putih sesuai takaran (hingga batas botol) sebelum digunakan, dan kocok dahulu sebelum di minum. sebaiknya diminum saat perut kosong (1 jam sebelum makan). jika mual, diminum setelah makan. dosis dan durasi pengobatan di tentukan oleh dokter berdasarkan jenis infeksi yang di obati.<br />\r\n&nbsp;</p>' WHERE `id_barang` = 281;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nAllopurinol 100mg/tab<br />\r\nIndikasi :<br />\r\nOba ini untuk menurunkan kadar asam urat.<br />\r\nEfek Samping :<br />\r\nkurangi makanan yang tinggi purin seperti jeroan, makanan laut &amp; beberapa sayuran hijau seperti bayam, dan kangkung, serta kacang kacangan seperti tahu dan tempe.<br />\r\nAturan Pakai :<br />\r\nobat ini di minum cukup sehari sekali 1 tablet sesudah makan pada waktu yang sama setiap hari.<br />\r\n&nbsp;</p>' WHERE `id_barang` = 282;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nMenthol 30%, champor 5%, olive oil 10%, essential oil (camellia sinensis) 0.25%, base ad 100%<br />\r\nIndikasi :<br />\r\nUntuk membantu meredakan pusing/masuk angin<br />\r\nEfek Samping :<br />\r\nistirahat yang cukup, makan-makanan yang bergizi dan minum obat sesuai gejala yg dialami.<br />\r\nAturan Pakai :<br />\r\ngosokkan pada bagian yang sakit.<br />\r\n&nbsp;</p>' WHERE `id_barang` = 286;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nTiap ml larutan mengandung :, phenol 5mg, benzocain 3mg<br />\r\nIndikasi :<br />\r\nUntuk menghilangkan rasa sakit pada sakit gigi.<br />\r\nEfek Samping :<br />\r\nhindari makanan/minuman manis, dan disarankan untuk menjaga kebersihan mulut dengan obat kumur.<br />\r\nAturan Pakai :<br />\r\nsemprotkan atau oleskan sedikit pada tempat yang sakit, dapat di ulang tiap 3-4 jam.<br />\r\n&nbsp;</p>' WHERE `id_barang` = 296;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nLoratadine 10mg/tab<br />\r\nIndikasi :<br />\r\nObat ini untuk gatal alergi.<br />\r\nEfek Samping :<br />\r\njangan berkendara setelah minum obat ini, karena dapat menyebabkan kantuk ringan, dan dianjurkan mengonsumsi obat ini pada malam hari.<br />\r\nAturan Pakai :<br />\r\ndosis :<br />\r\ndewasa, usia lanjut dan anak usia diatas 12 tahun : 1 tablet (10mg) dalam sehari.<br />\r\nanak usia 2-12 tahun :<br />\r\nBB &lt; 30kg : 5mg<br />\r\nBB &gt; 30kg : 10mg<br />\r\n&nbsp;</p>' WHERE `id_barang` = 298;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nTiap 5ml mengandung :, domperidone 5mg.<br />\r\nIndikasi :<br />\r\nObat ini untuk meredakan gejala mual dan muntah.<br />\r\nEfek Samping :<br />\r\nefek samping dari obat ini mulut kering, sakit kepala, dan diare. dan obat ini tidak dianjurkan untuk anak-anak.<br />\r\nAturan Pakai :<br />\r\ndewasa : 10-20mg tiap 8 jam, 30 menit sebelum makan. dan 10-20mg sekali sebelum tidur malam tergantung respon klinik. pengobatan jangan lebih dari 12 minggu.<br />\r\n&nbsp;</p>' WHERE `id_barang` = 299;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nAmbroxol HCI 15mg/ml<br />\r\nIndikasi :<br />\r\nObat ini untuk pengencer dahak pada anak/bayi<br />\r\nEfek Samping :<br />\r\nhindari makanan yang mengiritasi tenggorokan seperti makanan berminyak/berlemak serta makanan/minuman manis seperti permen,coklat, dan eskrim.<br />\r\nAturan Pakai :<br />\r\nanak-anak s/d 2 tahun : 0,5ml (10 tetes) tiap 12 jam, sesudah makan<br />\r\n&nbsp;</p>' WHERE `id_barang` = 301;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nAmbroxol HCI 30mg/tab<br />\r\nIndikasi :<br />\r\nObat ini untuk pengencer dahak.<br />\r\nEfek Samping :<br />\r\nhindari makanan yang mengiritasi tenggorokan seperti gorengan, makanan berminyak/berlemak, dan hindari makanan/minuman manis.<br />\r\nAturan Pakai :<br />\r\ndewasa : 1 kaplet tiap 8 jam sesudah makan.<br />\r\n&nbsp;</p>' WHERE `id_barang` = 302;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nNilai gizi per takaran saji :, calcium phosphate dihydrate 500 mg 10% akg, colecalciferol / vitamin d3 200 IU 35% akg, bahan tambahan : mannitol, sorbitol, lactose monohydrate, carmoisine AI lake, menthol, strawber<br />\r\nIndikasi :<br />\r\nSuplemen calcium ini untuk memelihara kesehatan tulang dan gigi.<br />\r\nEfek Samping :<br />\r\nsuplemen ini tidak boleh digunakan pada bayi di bawah 1 tahun.<br />\r\nAturan Pakai :<br />\r\nanak-anak : sehari 1 kaplet di kunyah.<br />\r\ndewasa : sehari 1-2 kaplet di kunyah.<br />\r\n&nbsp;</p>' WHERE `id_barang` = 305;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nChloramphenicol 1% (10mg tiap 1ml)<br />\r\nIndikasi :<br />\r\nUntuk meredakan gejala infeksi seperti nyeri, telinga berair, atau terasa penuh.<br />\r\nEfek Samping :<br />\r\nefek samping yang biasa terjadi, perih atau gatal.<br />\r\nAturan Pakai :<br />\r\ncara pakai : 2-3 tetes ke dalam liang telinga yang sakit, ulangi tiap 8 jam. miringkan kepala atau berbaring, teteskan obat, dan pertahankan posisi tsb selama 5-10 menit.<br />\r\n&nbsp;</p>' WHERE `id_barang` = 308;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nTiap gram salep mata mengandung :, dexamethasone sodium phosphate 1mg, neomycin sulfate 3,5mg, polymyxin B sulfate 6000 IU<br />\r\nIndikasi :<br />\r\nUntuk mengatasi peradangan mata yang disertai infeksi bakteri, seperti mata merah, bengkak, belekan atau nyeri.<br />\r\nEfek Samping :<br />\r\nsalep mata ini hanya boleh digunakan maksimal 1 bulan setelah kemasan dibuka untuk menghindari kontaminasi bakteri.<br />\r\nAturan Pakai :<br />\r\ncuci tangan yang bersih sebelum digunakan, tarik kelopak bawah mata, oleskan salep tanpa menyentuh ujung tube ke mata, tutup mata selama 1-2 menit, dan kedipkan mata perlahan agar salep merata. oleskan salep sekitar 1cm, tiap 8 jam.<br />\r\n&nbsp;</p>' WHERE `id_barang` = 309;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nSulfamethoxazole 200mg dan<br />\r\nIndikasi :<br />\r\nUntuk menbgobati infeksi bakteri saluran kemih, infeksi bakteri saluran pernafasan<br />\r\nEfek Samping :<br />\r\nUntuk membantu proses penyembuhan disarankan untuk beristirahat yang cukup, perbanyak minum air putih, dan makan sayur serta buah buahan.<br />\r\nAturan Pakai :<br />\r\n* 6-12 tahun: tiap 12 jam sekali 2 sendok obat<br />\r\n* 6bulan-6tahun: tiap 12 jam sekali 1 sendok obat<br />\r\ndiminum setelah makan, wajib dihabiskan<br />\r\n&nbsp;</p>' WHERE `id_barang` = 311;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nCefixime 100 mg/5 ml<br />\r\nIndikasi :<br />\r\nUntuk mengobati infeksi seperti saluran kencing, tonsilis, bronkitis akut<br />\r\nEfek Samping :<br />\r\nUntuk membantu proses penyembuhan disarankan untuk beristirahat yang cukup, perbanyak minum air putih, dan makan sayur serta buah buahan.<br />\r\nAturan Pakai :<br />\r\n*BB diatas 30kg: tiap 12 jam sekali, 1/2-1 sendok obat<br />\r\ndiminum setelah makan, kocok dahulu<br />\r\nwajib dihabiskan<br />\r\n&nbsp;</p>' WHERE `id_barang` = 312;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nCefadroxil 125mg/5ml<br />\r\nIndikasi :<br />\r\nMengobati infeksi saluran pernafasan (radang amandel/faringitis), kulit, jaringan lunak, dan saluran kemih<br />\r\nEfek Samping :<br />\r\nUntuk membantu proses penyembuhan disarankan untuk beristirahat yang cukup, perbanyak minum air putih, dan makan sayur serta buah buahan.<br />\r\nAturan Pakai :<br />\r\ndiminum tiap 12 jam sekali, 30-50mg/kgBB/hari<br />\r\nsesuai anjuran dokter, diminum setelah makan<br />\r\nwajib dihabiskan<br />\r\n&nbsp;</p>' WHERE `id_barang` = 313;
