UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nAl-hidroksida 200mg, Mg-hidroksida 200mg, simetikon 20mg<br />\r\nIndikasi :<br />\r\nUntuk mengatasi kembung, nyeri ulu hati akibat asam lambung berlebihan.<br />\r\nEfek Samping :<br />\r\nKonstipasi, diare, mual dan muntah.<br />\r\nAturan Pakai :<br />\r\ndiminum satu jam setelah makan dan sebelum tidur malam, di kunyah.<br />\r\n&nbsp;</p>' WHERE `id_barang` = 3470;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nTiap suppositoria mengandung: Benzocaine 1.0%, Zinc Oxide 2%, Aluminium Hydroxide 0.25% dalam massa hidrofil.<br />\r\nIndikasi :<br />\r\nSebagai obat pereda rasa nyeri/sakit pada wasir luar dan dalam, fisura ani (luka pada anus), dan proctitis (radang pada rektum).<br />\r\nEfek Samping :<br />\r\nHindari BAB Segera Setelah Memakai Obat: Setelah obat masuk, usahakan untuk tidak buang air besar setidaknya selama 1 hingga 2 jam ke depan agar zat aktif obat sempat terserap maksimal.<br />\r\nAturan Pakai :<br />\r\nMasukkan 1 supositoria ke dalam dubur, 1 kali sehari.<br />\r\n&nbsp;</p>' WHERE `id_barang` = 3610;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nOmeprazole 20mg<br />\r\nIndikasi :<br />\r\nUntuk asam lambung<br />\r\nEfek Samping :<br />\r\nMakan makanan mengandung basa (bayam, brokoli, alpukat, pisang, almond, chia seeds, kentang, ubi jalar)<br />\r\nAturan Pakai :<br />\r\nDiminum satu kali sehari 30menit sebelum makan.<br />\r\n&nbsp;</p>' WHERE `id_barang` = 3671;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nSimvastatin 20mg<br />\r\nIndikasi :<br />\r\nDigunakan untuk menurunkan kadar kolesterol total atau lemak jahat dalam darah<br />\r\nEfek Samping :<br />\r\nhindari mengonsumsi grapefruit atau jusnya saat menggunakan Selvim. Grapefruit mengandung senyawa yang dapat menghambat enzim pengurai Simvastatin, sehingga kadar obat di dalam darah bisa melonjak drastis dan memicu efek samping berbahaya. (seperti jeruk purut atau jeruk limau<br />\r\nAturan Pakai :<br />\r\ndiminum sekali sehari pada malam hari<br />\r\n&nbsp;</p>' WHERE `id_barang` = 3735;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nAtorvastatin 10mg<br />\r\nIndikasi :<br />\r\nObat menurunkan kadar kolesterol<br />\r\nEfek Samping :<br />\r\nusahakan minum atorvastatin di jam yang sama<br />\r\nAturan Pakai :<br />\r\ndiminum 1 x sehari sesuai anjuran dokter<br />\r\n&nbsp;</p>' WHERE `id_barang` = 4144;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nDextrose/glucose anyhydrous 2.70 gram, Sodium chloride 0.52 gram, Potassium chloride 0.30 gram, Trisodium citrate 0.58 gram<br />\r\nIndikasi :<br />\r\nMengobati Dehidrasi<br />\r\nEfek Samping :<br />\r\nInformasi efek samping spesifik belum tersedia. Hentikan penggunaan dan konsultasikan ke dokter/apoteker bila timbul reaksi yang tidak diinginkan<br />\r\nAturan Pakai :<br />\r\nlarutkan di air, minum sekuatnya<br />\r\n&nbsp;</p>' WHERE `id_barang` = 4547;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nDexamethasone 0,5mg<br />\r\nIndikasi :<br />\r\nAnti peradangan<br />\r\nEfek Samping :<br />\r\n-tidak boleh bagi penderita diabetes<br />\r\n-tidak boleh digunakan jangka panjang dan rutin<br />\r\n-perbanyak minum aie mineral<br />\r\n-hindari makanan gurih dan minuman instan manis<br />\r\nAturan Pakai :<br />\r\n3 kali sehari 1 tablet, atau sesuai petunjuk dokter<br />\r\n&nbsp;</p>' WHERE `id_barang` = 4776;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nMenthol 40%, camphor 20%, olive oil 10%, cajuput oil 12,5%, eucalyptus oil 12,5%.<br />\r\nIndikasi :<br />\r\nMinyak ini dapat meredakan pusing, mual.<br />\r\nEfek Samping :<br />\r\nistirahat yang cukup, dan banyak minum air putih untuk mempercepat proses penyembuhan. jika tidak kunjung hilang rasa pusingnya dapat menggunakan obat pereda pusing seperti paracetamol.<br />\r\nAturan Pakai :<br />\r\noleskan secukupnya.<br />\r\n&nbsp;</p>' WHERE `id_barang` = 5090;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nParacetamol 600 mg.<br />\r\nIndikasi :<br />\r\nMeredakan nyeri ringan hingga sedang seperti sakit kepala, sakit gigi, nyeri otot, serta menurunkan demam.<br />\r\nEfek Samping :<br />\r\nReaksi hipersensitivitas (alergi) seperti ruam kulit, gatal, atau bengkak (jarang).<br />\r\nAturan Pakai :<br />\r\n3 kali sehari setelah makan<br />\r\n&nbsp;</p>' WHERE `id_barang` = 5643;
